// Direct fuzz of the exporter + loader (not collected with src/).
#include "image.hpp"
#include "mem_init.h"
#include "scamptrie_dynamic.h"
#include <cstdio>
#include <cstdlib>
#include <map>
#include <random>
#include <set>
#include <vector>

static uint64_t rnd64(std::mt19937_64& g) { return g(); }

struct P { uint64_t hi, lo; uint32_t len, hop; };

int main(int argc, char** argv) {
    unsigned seed = argc > 1 ? (unsigned)atoi(argv[1]) : 1;
    int iters = argc > 2 ? atoi(argv[2]) : 2000;
    std::mt19937_64 g(seed);
    std::map<std::pair<uint64_t, uint64_t>, uint32_t> nulls;
    long total_rows = 0, max_rows = 0, nodes = 0;
    for (int it = 0; it < iters; ++it) {
        int mode = int(rnd64(g) % 6);
        int n = int(rnd64(g) % 400) + 1;
        std::vector<P> pfx;
        std::set<std::string> seen;
        int guard = 0;
        while ((int)pfx.size() < n && guard++ < n * 40) {
            uint64_t hi = rnd64(g), lo = rnd64(g);
            uint32_t len = uint32_t(rnd64(g) % 129);
            if (mode == 1) len = uint32_t(rnd64(g) % 17);
            if (mode == 2) len = 17 + uint32_t(rnd64(g) % 48);
            if (mode == 3) len = 65 + uint32_t(rnd64(g) % 64);
            if (mode == 4) { // clustered: share long prefixes, force fanout
                uint32_t cut = uint32_t(rnd64(g) % 120);
                hi = fib_mask_high(hi, cut > 64 ? 64 : cut);
                lo = fib_mask_high(lo, cut <= 64 ? 0 : cut - 64);
                len = cut > 128 ? 128 : len;
            }
            fib_normalize(hi, lo, len, hi, lo);
            char buf[48];
            snprintf(buf, sizeof(buf), "%016llx%016llx%u", (unsigned long long)hi, (unsigned long long)lo, len);
            if (!seen.insert(buf).second) continue;
            pfx.push_back(P{hi, lo, len, uint32_t(rnd64(g) % 4194303)});
        }
        Fib fib;
        for (size_t i = 0; i < pfx.size(); ++i) fib.insert(pfx[i].hi, pfx[i].lo, pfx[i].len, pfx[i].hop);
        ImageData img = build_image(fib);
        // shape invariants of our own export
        uint64_t rows = 0;
        for (int s = 0; s < RAM_NUM; ++s) rows += img.banks[s].size();
        total_rows += (long)rows;
        if ((long)rows > max_rows) max_rows = (long)rows;
        if (img.bitmaps.size() > 8193 || img.nexthops.size() > 8192) { printf("SIDE BOUND it=%d\n", it); return 1; }
        for (int s = 0; s < RAM_NUM; ++s) {
            if (img.banks[s].size() != (img.cells[s] + 1) / 2) { printf("ROW MISMATCH it=%d\n", it); return 1; }
            if (img.cells[s] > 131072) { printf("CELL BOUND it=%d\n", it); return 1; }
        }
        Fib back;
        if (!image_validate(img, back)) { printf("SELF VALIDATION FAILED it=%d n=%zu mode=%d\n", it, pfx.size(), mode); return 1; }
        if (back.size() != fib.size()) { printf("SIZE MISMATCH it=%d %zu %zu\n", it, back.size(), fib.size()); return 1; }
        // random lookups must agree between live model and image
        for (int q = 0; q < 60; ++q) {
            uint64_t hi = rnd64(g), lo = rnd64(g);
            if (q % 3 == 0 && !pfx.empty()) { size_t j = size_t(rnd64(g) % pfx.size()); hi = pfx[j].hi; lo = pfx[j].lo; }
            if (back.lookup(hi, lo) != fib.lookup(hi, lo)) { printf("LOOKUP MISMATCH it=%d\n", it); return 1; }
        }
        // every prefix survives with the same hop
        std::vector<FibPfx> all = back.all();
        for (size_t i = 0; i < all.size(); ++i) {
            const FibPfx& p = all[i];
            if (fib.lookup_upto(p.hi, p.lo, p.len) != p.hop) { printf("PREFIX LOSS it=%d\n", it); return 1; }
        }
        nodes += (long)all.size();
    }
    printf("fuzz seed=%u iters=%d ok; max_rows=%ld avg_rows=%ld prefixes/case=%ld\n",
           seed, iters, max_rows, total_rows / iters, nodes / iters);
    return 0;
}
CPP_EOF
